//! 🎟️ Original typed child schema and source retain exact native preparation receipts.
use super::*;
use crate::app::Emit;
use crate::test_app_mutation_fixture::{SetCount,TestMutation,TestSnapshot};
#[test]
fn original_child_preparation_preserves_native_receipts_and_cancellation(){
 let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};
 for count in[0,1,17]{for cut in[0,1,3,usize::MAX]{let((mut source,pointer),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let operations:Vec<TestMutation>=(0..count).map(|value|SetCount{value}.into()).collect();let pointer=operations.as_ptr();{let mut emit:Emit<TestMutation>=Emit::default();emit.child_preparations.push_back(ChildEmitPreparation::of_owned::<TestSnapshot,TestMutation>("slot","child",operations));(emit,pointer)}});let mut born=heap.requested_bytes;let mut released=heap.released_bytes;let mut turns=0;let mut ready=false;
  while turns<cut&&!ready{let demand=source.child_preparation_demands(grant.maximum_copy_bytes).unwrap();let mut denied=vec![RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}];if demand.copy_bytes>0{denied.push(RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..grant});}if demand.capacity_bytes>0{denied.push(RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes-1,..grant});}if demand.release_bytes>0{denied.push(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant});}
   for denied in denied{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.prepare_child_one(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));if let Some(preparation)=source.child_preparations.front_mut(){if let Some(original)=preparation.owner.as_any_mut().downcast_mut::<TypedChildEmitPreparation<TestMutation>>().unwrap().owned_source.as_ref(){assert_eq!(original.as_ptr(),pointer);}}if let Some(original)=source.owned_child_emits.last().and_then(|child|child.mutations::<TestMutation>()){assert_eq!(original.as_ptr(),pointer);}}
   let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.prepare_child_one(grant).unwrap());let progress=step.progress();assert!(progress.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;ready=matches!(step,ChildEmitPreparationStep::Ready(_));turns+=1;assert!(turns<100000);
  }
  loop{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.close_child_one(grant).unwrap());let Some(step)=step else{assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));break;};let progress=step.progress().unwrap_or_default();assert!(progress.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;turns+=1;assert!(turns<100000);}
  let((),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(source));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(born,released);println!("[DEBUG] original child preparation count={count} cancel={cut} turns={turns} sameTypedPointer physical={released} terminalDrop0");
 }}
}
